import json
from pathlib import Path

data_dir = Path('/app/data')
out_path = Path('/app/output/oscillation_report.json')
out_path.parent.mkdir(parents=True, exist_ok=True)

preferences = json.loads((data_dir/'preferences.json').read_text())
possible_solutions = json.loads((data_dir/'possible_solutions.json').read_text())
route_events = json.loads((data_dir/'route_events.json').read_text())

# --- Oscillation detection (preference-cycle) ---
pref = {int(k): int(v['prefer_via']) for k, v in preferences.items()}

def find_any_cycle(pref_map):
    visited_global = set()
    for start in pref_map:
        if start in visited_global:
            continue
        path = []
        seen_idx = {}
        cur = start
        while cur in pref_map:
            if cur in seen_idx:
                cycle = path[seen_idx[cur]:]
                return cycle
            if cur in visited_global:
                break
            seen_idx[cur] = len(path)
            path.append(cur)
            visited_global.add(cur)
            cur = pref_map[cur]
    return None

cycle = find_any_cycle(pref)
oscillation_detected = cycle is not None

# --- Route leak detection (valley-free violations) ---
leaks = []
for ev in route_events:
    # Violation if learned from provider/peer and exported to provider/peer
    src_t = ev.get('source_type')
    dst_t = ev.get('destination_type')
    if src_t in {'provider', 'peer'} and dst_t in {'provider', 'peer'}:
        leaks.append({
            'leaker_as': ev['advertiser_asn'],
            'source_as': ev['source_asn'],
            'destination_as': ev['destination_asn'],
            'source_type': src_t,
            'destination_type': dst_t,
        })

route_leak_detected = len(leaks) > 0

# --- Solution evaluation ---

def resolves_oscillation(sol: str) -> bool:
    s = sol.lower().strip()
    # Prohibited / non-root-cause actions
    if 'disable hub peering' in s or s.startswith('disable '):
        return False
    if 'restart bgp' in s or 'keepalive' in s or 'holdtime' in s:
        return False
    if 'route dampening' in s or 'wait for' in s or 'ecmp' in s:
        return False

    # Directly breaks preference cycle
    if 'update routing preference' in s and 'stop preferring' in s:
        return True
    if 'set route preference hierarchy' in s:
        return True

    # Breaks mutual dependency by removing one re-advertisement leg
    if 'filter out routes learned from hub2 before re-advertising' in s:
        return True

    return False


def resolves_route_leak(sol: str) -> bool:
    s = sol.lower().strip()
    # Must stop hub-to-hub advertisement of provider-learned routes.
    if 'no-export' in s and 'provider' in s and 'peer' in s:
        return True
    if 'export policy' in s and 'block announcing provider routes' in s and 'peer' in s:
        return True
    if 'route policy' in s and 'no-export' in s and 'provider routes' in s and 'peer' in s:
        return True

    # These do not stop advertising (they are receiver-side or selection-only)
    if 'ingress filtering' in s or 'rpki' in s or 'med' in s or 'as-path' in s:
        return False
    if 'user defined route' in s or 'routing intent' in s:
        return False

    return False

solution_results = {
    sol: {
        'oscillation_resolved': resolves_oscillation(sol) if oscillation_detected else False,
        'route_leak_resolved': resolves_route_leak(sol) if route_leak_detected else False,
    }
    for sol in possible_solutions
}

report = {
    'oscillation_detected': oscillation_detected,
    'oscillation_cycle': cycle or [],
    'affected_ases': sorted(set(cycle or [])),
    'route_leak_detected': route_leak_detected,
    'route_leaks': leaks,
    'solution_results': solution_results,
}

out_path.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')

# Verify output
text = out_path.read_text(encoding='utf-8')
json.loads(text)
assert out_path.stat().st_size > 0
print(out_path)
print(text)
